begin;

alter table public.site_events
  add column if not exists campaign_content jsonb not null default '{}'::jsonb;

update storage.buckets
set allowed_mime_types = array_append(allowed_mime_types, 'application/pdf')
where id = 'curileta-site-media'
  and allowed_mime_types is not null
  and not ('application/pdf' = any(allowed_mime_types));

with campaign_seed(slug, content) as (
  values
    ('halloween', '{"title":{"es":"La noche de las pequeñas calabazas","en":"The night of the little pumpkins"},"intro":{"es":"Curileta y Pompón descubren un bosque vestido de naranja. Hay luces entre los árboles, una adivinanza bajo la luna y dos máscaras listas para imprimir y colorear.","en":"Curileta and Pompón discover a forest dressed in orange. Lights glow between the trees, a riddle waits under the moon, and two masks are ready to print and color."},"activities":[{"id":"mascaras-y-coloreo","kind":"download","icon":"🎨","title":{"es":"Máscaras y bosque para colorear","en":"Masks and a forest to color"},"description":{"es":"Imprime las máscaras de Curileta y Pompón y una escena de Halloween para dibujar en familia.","en":"Print Curileta and Pompón masks and a Halloween scene to color together."},"reveal":{"es":"","en":""},"resourceUrl":"/files/events/halloween/curileta-halloween-printables.pdf","resourcePath":"static:resource:halloween-printables"},{"id":"acertijo-luna","kind":"reveal","icon":"🌙","title":{"es":"El acertijo de la luna","en":"The moon riddle"},"description":{"es":"Tengo una cara redonda y brillo en la noche. A veces parezco una sonrisa y otras, un círculo completo. ¿Quién soy?","en":"I have a round face and glow at night. Sometimes I look like a smile, and sometimes a full circle. What am I?"},"reveal":{"es":"¡La luna! Esta noche acompaña a quienes exploran el bosque con curiosidad y amabilidad.","en":"The moon! Tonight it keeps company with everyone exploring the forest with curiosity and kindness."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('christmas', '{"title":{"es":"La ruta de las luces de invierno","en":"The winter lights trail"},"intro":{"es":"El bosque se cubre de nieve y pequeñas luces guían a Curileta y Pompón. Cada parada invita a compartir un deseo, ayudar a alguien o descubrir una historia junto a una taza calentita.","en":"Snow settles over the forest as little lights guide Curileta and Pompón. Each stop invites a kind wish, a helpful gesture or a story shared over something warm."},"activities":[{"id":"ruta-de-luces","kind":"reveal","icon":"🕯️","title":{"es":"Sigue las tres luces","en":"Follow the three lights"},"description":{"es":"Imagina tres luces en el camino. ¿Qué gesto amable podría esconder cada una?","en":"Picture three lights along the path. What kind gesture might be waiting at each one?"},"reveal":{"es":"Una luz guarda una palabra amable, otra ofrece ayuda y la tercera invita a compartir. Elige una y llévala contigo hoy.","en":"One light holds a kind word, another offers help and the third invites sharing. Choose one and carry it with you today."},"resourceUrl":"","resourcePath":""},{"id":"deseo-de-invierno","kind":"reveal","icon":"⭐","title":{"es":"Un deseo para el bosque","en":"A wish for the forest"},"description":{"es":"Piensa en un deseo que también ayude a otra persona, un animal o un lugar.","en":"Think of a wish that could also help another person, an animal or a place."},"reveal":{"es":"Los deseos crecen cuando se convierten en pequeños gestos. ¿Qué primer paso puedes dar?","en":"Wishes grow when they become small actions. What first step could you take?"},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('easter', '{"title":{"es":"La búsqueda de los huevos de primavera","en":"The spring egg hunt"},"intro":{"es":"Entre flores recién abiertas, Curileta encuentra pistas de colores que llevan a un claro soleado. Mira con atención: cada huevo esconde una forma, un color y una pregunta sobre la naturaleza.","en":"Among fresh flowers, Curileta finds colorful clues leading to a sunny clearing. Look closely: each egg hides a shape, a color and a question about nature."},"activities":[{"id":"pista-de-colores","kind":"reveal","icon":"🥚","title":{"es":"La pista de los colores","en":"The color clue"},"description":{"es":"Encuentra a tu alrededor algo amarillo, algo verde y algo que huela a primavera.","en":"Find something yellow, something green and something that smells like spring."},"reveal":{"es":"¡Pista completada! Los colores y aromas también cuentan historias sobre cómo despierta la naturaleza.","en":"Clue found! Colors and scents tell stories about nature waking up."},"resourceUrl":"","resourcePath":""},{"id":"semilla-sorpresa","kind":"reveal","icon":"🌱","title":{"es":"La semilla sorpresa","en":"The surprise seed"},"description":{"es":"¿Qué tres cosas necesita una semilla para empezar a crecer?","en":"What three things does a seed need to begin growing?"},"reveal":{"es":"Agua, luz y un lugar donde echar raíces. Después, paciencia y cuidados.","en":"Water, light and a place to take root. Then it needs time and care."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('valentines', '{"title":{"es":"Pequeños gestos que acercan","en":"Little things that bring us closer"},"intro":{"es":"Curileta y Pompón recorren un sendero de amistad. No hace falta un gran regalo: escuchar, dar las gracias y compartir una aventura también son maneras de decir que alguien te importa.","en":"Curileta and Pompón follow a friendship trail. It does not take a grand gift: listening, saying thanks and sharing an adventure are ways to show someone matters."},"activities":[{"id":"buzon-amable","kind":"reveal","icon":"💌","title":{"es":"Un mensaje amable","en":"A kind message"},"description":{"es":"Piensa en alguien a quien quieras agradecer algo. ¿Qué frase breve podrías decirle?","en":"Think of someone you would like to thank. What short sentence could you share?"},"reveal":{"es":"Puedes empezar con “Gracias por…” o “Me gusta cuando…”. Un mensaje sincero puede alegrar el día.","en":"You could begin with “Thank you for…” or “I like it when…”. A sincere message can brighten a day."},"resourceUrl":"","resourcePath":""},{"id":"mapa-amistad","kind":"reveal","icon":"🧭","title":{"es":"El mapa de la amistad","en":"The friendship map"},"description":{"es":"Nombra una cosa que disfrutas hacer con otra persona.","en":"Name one thing you enjoy doing with another person."},"reveal":{"es":"Las amistades crecen con tiempo compartido, respeto y espacio para que cada persona sea ella misma.","en":"Friendships grow through shared time, respect and room for everyone to be themselves."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('new-year', '{"title":{"es":"Un año lleno de nuevos caminos","en":"A year of new paths"},"intro":{"es":"En la última noche del año, Curileta despliega un mapa en blanco. El grupo dibuja lugares por descubrir, cosas por aprender y maneras de cuidar a sus amistades durante el camino.","en":"On the year’s last night, Curileta opens a blank map. The friends draw places to discover, things to learn and ways to care for one another along the way."},"activities":[{"id":"mapa-de-deseos","kind":"reveal","icon":"🗺️","title":{"es":"Mapa de tres caminos","en":"A map with three paths"},"description":{"es":"Elige un camino para aprender, otro para explorar y uno para ayudar.","en":"Choose one path for learning, one for exploring and one for helping."},"reveal":{"es":"No tienes que recorrerlos todos hoy. Escoge un primer paso pequeño y celebra cuando lo completes.","en":"You do not have to travel them all today. Pick one small first step and celebrate when you finish it."},"resourceUrl":"","resourcePath":""},{"id":"cuenta-regresiva","kind":"reveal","icon":"✨","title":{"es":"Tres cosas que guardas","en":"Three things to keep"},"description":{"es":"Recuerda algo que aprendiste, algo que te hizo reír y alguien que te acompañó.","en":"Remember something you learned, something that made you laugh and someone who was there for you."},"reveal":{"es":"Cada recuerdo es una pequeña luz para llevar al nuevo año.","en":"Every memory is a little light to carry into the new year."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('lunar-new-year', '{"title":{"es":"Faroles para empezar de nuevo","en":"Lanterns for a fresh beginning"},"intro":{"es":"Curileta sigue faroles de papel hasta la plaza, donde las familias se reúnen para compartir comida, deseos y relatos. La celebración cambia entre comunidades: cada una guarda sus propias costumbres.","en":"Curileta follows paper lanterns to the square, where families gather to share food, wishes and stories. Traditions differ across communities, and each has its own customs."},"activities":[{"id":"deseo-luminoso","kind":"reveal","icon":"🏮","title":{"es":"Un deseo luminoso","en":"A bright wish"},"description":{"es":"Piensa en un deseo para tu comunidad, tu familia o tus amistades.","en":"Think of a wish for your community, family or friends."},"reveal":{"es":"Los nuevos comienzos se celebran de muchas formas. Un deseo también puede convertirse en una promesa de cuidado.","en":"Fresh beginnings are celebrated in many ways. A wish can also become a promise to care."},"resourceUrl":"","resourcePath":""},{"id":"animal-del-zodiaco","kind":"reveal","icon":"🐉","title":{"es":"Un animal imaginario","en":"An imaginary animal"},"description":{"es":"Inventa un animal guardián para tu farol. ¿Qué cualidad especial tendría?","en":"Invent a guardian animal for your lantern. What special quality would it have?"},"reveal":{"es":"Podría tener valentía, paciencia o un oído atento. ¡Tu historia decide qué lo hace especial!","en":"It might have courage, patience or a listening ear. Your story decides what makes it special!"},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('spring', '{"title":{"es":"El jardín que despierta","en":"The garden waking up"},"intro":{"es":"Brotes, pétalos y mariposas transforman los caminos del bosque. Curileta anota los cambios que observa para descubrir qué necesitan las plantas y cómo compartir el jardín con los animales.","en":"New shoots, petals and butterflies transform the forest paths. Curileta records what changes to learn what plants need and how to share the garden with animals."},"activities":[{"id":"exploracion-botanica","kind":"reveal","icon":"🌼","title":{"es":"Busca una señal de primavera","en":"Find a sign of spring"},"description":{"es":"Mira por una ventana o sal a un lugar seguro y observa un cambio en una planta o árbol.","en":"Look through a window or visit a safe outdoor place and notice a change in a plant or tree."},"reveal":{"es":"Una hoja nueva, un botón o una rama con flores son pistas. Obsérvalas sin arrancarlas.","en":"A fresh leaf, a bud or a flowering branch are clues. Observe without picking them."},"resourceUrl":"","resourcePath":""},{"id":"semillero","kind":"reveal","icon":"🦋","title":{"es":"¿Quién visita las flores?","en":"Who visits the flowers?"},"description":{"es":"Adivina qué animales ayudan a transportar polen entre las flores.","en":"Guess which animals help carry pollen between flowers."},"reveal":{"es":"Abejas, mariposas y otros polinizadores visitan flores. Podemos ayudar protegiendo sus hábitats.","en":"Bees, butterflies and other pollinators visit flowers. We can help by protecting their habitats."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('summer', '{"title":{"es":"Una aventura entre sol y mar","en":"An adventure between sun and sea"},"intro":{"es":"Los amigos siguen la brisa hasta la costa. Allí descubren pozas, aves y formas de refrescarse con cuidado: sombra, agua y atención al entorno forman parte de la aventura.","en":"The friends follow the breeze to the coast. They discover tide pools, birds and thoughtful ways to stay cool: shade, water and care for the surroundings are part of the adventure."},"activities":[{"id":"detective-de-mareas","kind":"reveal","icon":"🌊","title":{"es":"Detectives de la costa","en":"Coast detectives"},"description":{"es":"Imagina una poza entre rocas. ¿Qué harías para observarla sin dañar a sus habitantes?","en":"Imagine a tide pool among rocks. How could you explore without harming its inhabitants?"},"reveal":{"es":"Mira sin tocar ni sacar animales, deja cada piedra donde estaba y comparte el lugar con calma.","en":"Look without touching or removing animals, leave rocks where they were and share the place gently."},"resourceUrl":"","resourcePath":""},{"id":"brujula-solar","kind":"reveal","icon":"☀️","title":{"es":"La brújula del sol","en":"The sun compass"},"description":{"es":"¿Qué puedes llevar para cuidarte en un día soleado al aire libre?","en":"What could you bring to care for yourself on a sunny day outside?"},"reveal":{"es":"Agua, sombra, ropa adecuada y protección solar. Pide ayuda a una persona adulta para preparar la salida.","en":"Water, shade, suitable clothing and sun protection. Ask an adult to help prepare for the outing."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('autumn', '{"title":{"es":"El viaje de las hojas viajeras","en":"The journey of the wandering leaves"},"intro":{"es":"Una brisa dorada lleva a Curileta y Pompón por el bosque. Siguen semillas, hojas y bellotas para descubrir cómo los animales se preparan para los meses fríos.","en":"A golden breeze carries Curileta and Pompón through the woods. They follow seeds, leaves and acorns to learn how animals prepare for colder months."},"activities":[{"id":"coleccion-de-colores","kind":"reveal","icon":"🍂","title":{"es":"Paleta de otoño","en":"Autumn palette"},"description":{"es":"Encuentra o imagina tres colores que ves en las hojas de otoño.","en":"Find or imagine three colors you see in autumn leaves."},"reveal":{"es":"Cada árbol cambia a su ritmo. Los colores dependen de la especie, el clima y el lugar.","en":"Each tree changes at its own pace. Colors depend on the species, weather and place."},"resourceUrl":"","resourcePath":""},{"id":"despensa-del-bosque","kind":"reveal","icon":"🌰","title":{"es":"La despensa del bosque","en":"The forest pantry"},"description":{"es":"¿Qué podría guardar una ardilla para los días fríos?","en":"What might a squirrel save for colder days?"},"reveal":{"es":"Semillas y frutos como las bellotas. Dejamos la comida silvestre en su lugar para los animales.","en":"Seeds and nuts such as acorns. We leave wild food where it is for the animals."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('earth-day', '{"title":{"es":"Pequeñas acciones para cuidar la Tierra","en":"Small ways to care for Earth"},"intro":{"es":"El bosque, el mar y las ciudades forman parte de un hogar compartido. Curileta propone mirar alrededor y elegir una acción posible para cuidar agua, energía, plantas o animales.","en":"Forests, oceans and cities are all part of a shared home. Curileta invites everyone to look around and choose one doable way to care for water, energy, plants or animals."},"activities":[{"id":"detectives-de-habitat","kind":"reveal","icon":"🔎","title":{"es":"Detectives de un lugar","en":"Place detectives"},"description":{"es":"Elige un rincón cercano. ¿Qué seres vivos lo usan y qué necesitan?","en":"Choose a nearby place. What living things use it, and what do they need?"},"reveal":{"es":"Agua limpia, alimento, refugio y espacio ayudan a muchos seres vivos. Cuidar un lugar empieza por conocerlo.","en":"Clean water, food, shelter and space help many living things. Caring for a place starts by getting to know it."},"resourceUrl":"","resourcePath":""},{"id":"reto-pequeno","kind":"reveal","icon":"🌍","title":{"es":"Reto de cinco minutos","en":"A five-minute challenge"},"description":{"es":"Piensa en una pequeña forma de reducir residuos o ahorrar agua hoy.","en":"Think of one small way to reduce waste or save water today."},"reveal":{"es":"Reutilizar una hoja, cerrar el grifo mientras te cepillas o recoger basura con ayuda son buenos comienzos.","en":"Reusing a sheet of paper, turning off the tap while brushing or picking up litter with help are good starts."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('world-book-day', '{"title":{"es":"Una puerta a otros mundos","en":"A doorway to other worlds"},"intro":{"es":"Cada libro es un pasadizo a otra vida, lugar o época. Curileta abre su cuaderno de aventuras y anima a lectores de todas las edades a compartir historias sin importar dónde las encontraron.","en":"Every book is a passage to another life, place or time. Curileta opens an adventure notebook and invites readers of all ages to share stories, wherever they found them."},"activities":[{"id":"objeto-protagonista","kind":"reveal","icon":"📚","title":{"es":"Un objeto protagonista","en":"An object becomes a hero"},"description":{"es":"Elige un objeto cercano. ¿Qué aventura viviría si pudiera hablar?","en":"Choose an object nearby. What adventure would it have if it could talk?"},"reveal":{"es":"Empieza con un lugar inesperado, una pregunta curiosa y alguien que necesite ayuda. Ya tienes una historia.","en":"Start with an unexpected place, a curious question and someone who needs help. You have a story."},"resourceUrl":"","resourcePath":""},{"id":"recomendacion-lectora","kind":"reveal","icon":"🔖","title":{"es":"Recomienda una historia","en":"Recommend a story"},"description":{"es":"Piensa en un libro, cuento o relato que compartirías con otra persona.","en":"Think of a book, tale or story you would share with someone else."},"reveal":{"es":"Cuéntale qué te hizo sentir, qué personaje recuerdas y por qué te gustaría que lo leyera.","en":"Tell them how it made you feel, which character you remember and why you hope they read it."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('pride', '{"title":{"es":"Un lugar para ser quien eres","en":"A place to be yourself"},"intro":{"es":"El arcoíris del bosque reúne colores diferentes sin borrar ninguno. Curileta celebra la diversidad, la dignidad y la amistad, y recuerda que cada persona merece respeto y seguridad.","en":"The forest rainbow brings many colors together without hiding any. Curileta celebrates diversity, dignity and friendship, and remembers that everyone deserves respect and safety."},"activities":[{"id":"arcoiris-de-valores","kind":"reveal","icon":"🌈","title":{"es":"Un color, una cualidad","en":"One color, one quality"},"description":{"es":"Elige un color del arcoíris y piensa en una cualidad que ayuda a cuidar a otras personas.","en":"Choose a rainbow color and think of a quality that helps care for others."},"reveal":{"es":"Escuchar, respetar, incluir y defender a quien necesita apoyo hacen más seguro el camino para todos.","en":"Listening, respecting, including and standing up for someone who needs support makes the path safer for everyone."},"resourceUrl":"","resourcePath":""},{"id":"amabilidad-compartida","kind":"reveal","icon":"🤝","title":{"es":"Una invitación amable","en":"A kind invitation"},"description":{"es":"¿Cómo podrías invitar a alguien a participar sin presionarlo?","en":"How could you invite someone to join without putting pressure on them?"},"reveal":{"es":"Puedes ofrecer la invitación, escuchar la respuesta y respetar lo que esa persona decida.","en":"You can offer an invitation, listen to the answer and respect what that person decides."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('st-patrick', '{"title":{"es":"La senda verde y el trébol curioso","en":"The green path and the curious clover"},"intro":{"es":"Un trébol brillante señala un camino por colinas verdes. Curileta y Pompón siguen las pistas mientras aprenden que las leyendas viajan entre culturas y se cuentan de muchas maneras.","en":"A bright clover points toward a path across green hills. Curileta and Pompón follow clues and learn that legends travel between cultures and are told in many ways."},"activities":[{"id":"busqueda-de-formas","kind":"reveal","icon":"🍀","title":{"es":"Encuentra una forma","en":"Find a shape"},"description":{"es":"Busca una hoja o una ilustración con forma de corazón, estrella o trébol.","en":"Find a leaf or picture shaped like a heart, star or clover."},"reveal":{"es":"¡Pista encontrada! Las formas se repiten en la naturaleza, pero cada hoja sigue siendo distinta.","en":"Clue found! Shapes repeat in nature, but every leaf is still different."},"resourceUrl":"","resourcePath":""},{"id":"leyenda-inventada","kind":"reveal","icon":"🎻","title":{"es":"Inventa una leyenda","en":"Invent a legend"},"description":{"es":"¿Qué pequeño tesoro podría proteger un trébol en tu historia?","en":"What little treasure might a clover protect in your story?"},"reveal":{"es":"Puede guardar una canción, una semilla o una promesa de amistad. Las leyendas crecen con la imaginación.","en":"It could keep a song, a seed or a promise of friendship. Legends grow through imagination."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('day-of-the-dead', '{"title":{"es":"Un sendero de flores y recuerdos","en":"A path of flowers and memories"},"intro":{"es":"Flores de colores iluminan un camino para recordar con cariño a quienes forman parte de nuestras historias. Curileta escucha relatos familiares con respeto: cada comunidad vive esta tradición a su manera.","en":"Colorful flowers light a path for remembering people who are part of our stories. Curileta listens to family memories with care: each community lives this tradition in its own way."},"activities":[{"id":"flor-del-recuerdo","kind":"reveal","icon":"🌼","title":{"es":"Una flor para recordar","en":"A flower to remember"},"description":{"es":"Piensa en una persona o animal querido y en una cosa bonita que recuerdes.","en":"Think of someone or an animal you love and one kind memory you have."},"reveal":{"es":"Compartir recuerdos puede acercarnos. Si algo te pone triste, puedes hablar con una persona adulta de confianza.","en":"Sharing memories can bring us closer. If something makes you sad, you can talk with a trusted adult."},"resourceUrl":"","resourcePath":""},{"id":"camino-de-colores","kind":"reveal","icon":"🕯️","title":{"es":"El camino de los colores","en":"The path of colors"},"description":{"es":"Imagina que cada pétalo lleva un recuerdo amable. ¿Qué color escogerías?","en":"Imagine every petal carries a kind memory. Which color would you choose?"},"reveal":{"es":"No hay una respuesta única. Las flores, comidas y formas de recordar cambian de una familia a otra.","en":"There is no single answer. Flowers, foods and ways of remembering differ from one family to another."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('world-childrens-day', '{"title":{"es":"Un mundo donde cada infancia cuenta","en":"A world where every childhood matters"},"intro":{"es":"Curileta y Pompón recorren un mapa hecho de juegos, ideas y voces pequeñas que merecen ser escuchadas. La aventura recuerda que la infancia necesita cuidado, oportunidades, descanso y un trato justo.","en":"Curileta and Pompón travel across a map made of play, ideas and young voices worth hearing. Their adventure remembers that children need care, opportunity, rest and fair treatment."},"activities":[{"id":"mapa-de-derechos","kind":"reveal","icon":"🧩","title":{"es":"Una pieza importante","en":"An important piece"},"description":{"es":"Piensa en algo que todos los niños y niñas necesitan para crecer con bienestar.","en":"Think of something every child needs to grow up well."},"reveal":{"es":"Cuidado, educación, juego, salud, protección y ser escuchados son parte de una infancia digna.","en":"Care, education, play, health, protection and being heard are part of a dignified childhood."},"resourceUrl":"","resourcePath":""},{"id":"idea-para-comunidad","kind":"reveal","icon":"🗣️","title":{"es":"Una idea para tu comunidad","en":"An idea for your community"},"description":{"es":"¿Qué cambiarías para que niñas y niños puedan jugar o aprender mejor cerca de casa?","en":"What would you change so children can play or learn better near home?"},"reveal":{"es":"Las ideas de la infancia merecen atención. Comparte la tuya con una persona adulta de confianza.","en":"Children’s ideas deserve attention. Share yours with a trusted adult."},"resourceUrl":"","resourcePath":""}]}'::jsonb),
    ('diwali', '{"title":{"es":"La senda de las pequeñas luces","en":"The trail of little lights"},"intro":{"es":"Faroles y lámparas iluminan una senda de celebración. Curileta acompaña a las familias que la invitan a conocer Diwali, una festividad que se vive de formas distintas según la región, la fe y las costumbres.","en":"Lanterns and lamps brighten a celebration trail. Curileta joins families who invite her to learn about Diwali, a festival celebrated in different ways across regions, faiths and customs."},"activities":[{"id":"luz-compartida","kind":"reveal","icon":"🪔","title":{"es":"Una luz para compartir","en":"A light to share"},"description":{"es":"Piensa en una acción que pueda dar ánimo o ayuda a alguien hoy.","en":"Think of an action that could encourage or help someone today."},"reveal":{"es":"Una palabra amable, un rato de escucha o una mano con una tarea pueden ser pequeñas luces.","en":"A kind word, time to listen or a hand with a task can be little lights."},"resourceUrl":"","resourcePath":""},{"id":"patron-de-lamparas","kind":"reveal","icon":"✨","title":{"es":"Diseña un patrón luminoso","en":"Design a light pattern"},"description":{"es":"Inventa un patrón de tres formas y dos colores para decorar un farol de papel imaginario.","en":"Invent a pattern of three shapes and two colors for an imaginary paper lantern."},"reveal":{"es":"Repetir formas ayuda a crear ritmo. Puedes dibujarlo en una hoja y compartir tu diseño.","en":"Repeating shapes creates rhythm. You can draw it on paper and share your design."},"resourceUrl":"","resourcePath":""}]}'::jsonb)
)
update public.site_events as event
set campaign_content = seed.content,
    updated_at = now()
from campaign_seed as seed
where event.slug = seed.slug
  and (event.campaign_content = '{}'::jsonb or event.campaign_content->'activities' is null);

-- Strengthen the existing preset packs while preserving any custom admin choices.
update public.site_events as event
set effects = jsonb_set(
  jsonb_set(
    jsonb_set(
      event.effects,
      '{decorations}',
      coalesce((
        select jsonb_agg(to_jsonb(decoration) order by decoration)
        from (
          select current_decoration.decoration
          from jsonb_array_elements_text(coalesce(event.effects->'decorations', '[]'::jsonb)) as current_decoration(decoration)
          union
          select added_decoration.decoration
          from jsonb_array_elements_text(case event.slug
            when 'halloween' then '["fog"]'::jsonb
            when 'christmas' then '["snowbanks","snowman","garlands"]'::jsonb
            when 'easter' then '["confetti"]'::jsonb
            when 'valentines' then '["confetti"]'::jsonb
            when 'new-year' then '["confetti"]'::jsonb
            when 'lunar-new-year' then '["paperLanterns","confetti"]'::jsonb
            when 'spring' then '["fireflies"]'::jsonb
            when 'summer' then '["bunting"]'::jsonb
            when 'autumn' then '["fog"]'::jsonb
            when 'earth-day' then '["fireflies"]'::jsonb
            when 'world-book-day' then '["fireflies"]'::jsonb
            when 'pride' then '["bunting","confetti"]'::jsonb
            when 'st-patrick' then '["confetti"]'::jsonb
            when 'day-of-the-dead' then '["paperLanterns"]'::jsonb
            when 'world-childrens-day' then '["bunting","confetti"]'::jsonb
            when 'diwali' then '["paperLanterns"]'::jsonb
            else '[]'::jsonb
          end) as added_decoration(decoration)
        ) as merged_decorations
      ), '[]'::jsonb),
      true
    ),
    '{decorationCount}',
    case when event.effects->>'decorationCount' = '14' then '24'::jsonb else coalesce(event.effects->'decorationCount', '24'::jsonb) end,
    true
  ),
  '{decorationOpacity}',
  case when event.effects->>'decorationOpacity' = '0.32' then '0.56'::jsonb else coalesce(event.effects->'decorationOpacity', '0.56'::jsonb) end,
  true
),
    updated_at = now()
where event.slug in (
  'halloween', 'christmas', 'easter', 'valentines', 'new-year', 'lunar-new-year', 'spring', 'summer',
  'autumn', 'earth-day', 'world-book-day', 'pride', 'st-patrick', 'day-of-the-dead', 'world-childrens-day', 'diwali'
);

commit;
